        result("r3", "ads", "label", "样本-1", value="z"),
    ],
    "lineage": {
        "datasets": ["ods", "dwd", "ads"],
        "fields": {"ods": ["name"], "dwd": ["label"], "ads": ["label"]},
        "edges": [
